6	//  Latchkey
7	//
8	//  JavaScript the app injects into the dashboard, as source text only.
9	//
10	//  Kept apart from the `WKUserScript` construction (PageScripts.swift) and
11	//  free of WebKit, so `scripts/test-page-scripts.sh` can compile this file on
12	//  the host, print a script, and run it under Node against a fake `location`
13	//  and `history`. The test exercises the exact text the app injects.
14	//
15	
16	import Foundation
17	
18	enum PageScriptSources {
19	    /// Removes `token` from the address at document start (revision R2).
20	    ///
21	    /// A sign-in link is `https://<gateway>/?token=…`. By the time any script
22	    /// on that page runs, the token has already done its job: KiroCrew's auth
23	    /// middleware serves the page and sets the session and refresh cookies on
24	    /// that same response (`dashboard/token_auth.py:2891-3037` in 0.6.0).
25	    /// Leaving it in the address keeps a credential that is re-redeemable for
26	    /// 300 s in the back-forward list and in anything that reads the URL.
27	    ///
28	    /// Why document start, before the page's own scripts:
29	    ///  - React Router snapshots the location when it initialises. Rewriting
30	    ///    the URL after that leaves the router believing the query still holds
31	    ///    the token, and its next `setSearchParams` would write it back.
32	    ///  - It turns every sign-in load into the ordinary cookie-authenticated
33	    ///    load the app makes on every cold start, which is the most exercised
34	    ///    path the dashboard has.
35	    ///
36	    /// Cost, accepted: KiroCrew 0.6.0 reads `?token=` for one optional
37	    /// feature — a token carrying a `prompt` claim prefills the chat
38	    /// (`App-*.js`, the effect that calls its `YA()` decoder). Sign-in links
39	    /// minted by `kirocrew token` or the phone-access QR carry no prompt, so
40	    /// nothing is lost for them.
41	    ///
42	    /// Other parameters and the fragment are preserved; only `token` goes.
43	    /// `history.state` is passed through so the router's own state survives.
44	    static let stripSignInToken = #"""
45	    (function () {
46	      try {
47	        var params = new URLSearchParams(window.location.search);
48	        if (!params.has('token')) { return; }
49	        params.delete('token');
50	        var rest = params.toString();
51	        var clean = window.location.pathname + (rest ? '?' + rest : '') + window.location.hash;
52	        window.history.replaceState(window.history.state, '', clean);
53	      } catch (e) {
54	        // Never break the page over this. The token then stays in the
55	        // address, which is exactly the pre-R2 behaviour.
56	      }
57	    })();
58	    """#
59	
60	    /// The id of the `<style>` element `sessionBridge` adds.
61	    static let bannerStyleID = "latchkey-session-banner-hidden"
62	
63	    /// The session bridge (M4.2, R21, R22). Runs in the app's own content
64	    /// world, main frame only, at document start — so it is re-injected on
65	    /// every navigation, including the `location.assign('/')` KiroCrew does
66	    /// when a refresh chain is revoked, after which `mc-auth-required` fires.
67	    ///
68	    /// Three jobs:
69	    ///  1. Forward KiroCrew's `mc-auth-required` / `mc-auth-cleared` window
70	    ///     events to native. DOM events reach listeners in every content
71	    ///     world; the message handler exists only in the app's world, so the
72	    ///     page (or anything it loads from a CDN) cannot post to it.
73	    ///  2. Hide the page's own `#mc-session-expired` banner with CSS ONLY
74	    ///     (R22): the native sheet replaces it. Never remove the element or
75	    ///     click its ✕ — a startup gate reads it, and ✕ clears the client's
76	    ///     latches. `display:none` also keeps its input from autofocusing and
77	    ///     popping the keyboard.
78	    ///  3. Say `ready`. If native does not hear it, it removes the style again
79	    ///     (`revealSessionBanner`), so a broken bridge leaves the page's own
80	    ///     banner as the way to sign in. With no message handler at all the
81	    ///     style is never added in the first place.
82	    static let sessionBridge = #"""
83	    (function () {
84	      var handlers = window.webkit && window.webkit.messageHandlers;
85	      var handler = handlers && handlers.kiroSession;
86	      if (!handler) { return; }
87	      function post(event) {
88	        try { handler.postMessage({ event: event }); } catch (e) {}
89	      }
90	      try {
91	        var style = document.createElement('style');
92	        style.id = 'latchkey-session-banner-hidden';
93	        style.textContent = '#mc-session-expired{display:none!important}';
94	        (document.head || document.documentElement).appendChild(style);
95	      } catch (e) {}
96	      window.addEventListener('mc-auth-required', function () { post('auth-required'); });
97	      window.addEventListener('mc-auth-cleared', function () { post('auth-cleared'); });
98	      post('ready');
99	    })();
100	    """#
101	
102	    /// Undoes `sessionBridge`'s banner hiding: the handshake's fallback (R22).
103	    static let revealSessionBanner = #"""
104	    (function () {
105	      var s = document.getElementById('latchkey-session-banner-hidden');
106	      if (s) { s.remove(); }
107	    })();
108	    """#
109	
110	    /// The body of the async function the app runs in its own content world
111	    /// to ask the gateway something AS THE PAGE: M4's `/api/auth/me` check,
112	    /// and R32's `POST /api/auth/logout`. Arguments `path`, `method` and
113	    /// `timeoutMs` (0: none). Returns the HTTP status.
114	    ///
115	    /// Why the page and not URLSession: the request must carry the page's
116	    /// cookies (HttpOnly; the refresh cookie is scoped to /api/auth) and its
117	    /// Origin, which the gateway's CSRF check compares. `same-origin`
118	    /// credentials is the contract -- `omit` would make the logout a no-op
119	    /// that still answers 200. The header only marks the app's own requests,
120	    /// so the test gateway can tell them from the page's identical calls;
121	    /// servers ignore it. The abort is what keeps a check or a sign-out from
122	    /// hanging on a gateway that is down, or on a connection that is open
123	    /// and answers nothing; every caller in the app passes a timeout
124	    /// (`SessionManager.checkTimeout`, `DashboardSignOut.requestTimeout`).
125	    /// 0 still means none, for the contract's sake, but nothing sends it.
126	    static let sessionFetch = #"""
127	    const controller = new AbortController();
128	    const timer = timeoutMs > 0 ? setTimeout(function () { controller.abort(); }, timeoutMs) : null;
129	    try {
130	      const r = await fetch(path, {method: method, credentials: 'same-origin', cache: 'no-store',
131	                                   headers: {'X-Latchkey-Check': '1'}, signal: controller.signal});
132	      return r.status;
133	    } finally {
134	      if (timer !== null) { clearTimeout(timer); }
135	    }
136	    """#
137	
138	    /// The JSON-answering sibling of `sessionFetch`, for a share (F3 §4.5):
139	    /// the slot list, the folders and the post. Arguments `path`, `method`,
140	    /// `body` (a JSON string, or null), `shareId` and `timeoutMs`. Returns
141	    /// `{status, body, auth}` -- the status, the response text and whether
142	    /// `X-Auth-Required` came back -- or `{status: 0}` when the request got
143	    /// no answer (network, abort). As the page, for the reasons
144	    /// `sessionFetch` gives; the header names the item, so the test gateway
145	    /// can tell a share's requests from the page's.
146	    static let shareFetch = #"""
147	    const controller = new AbortController();
148	    const timer = timeoutMs > 0 ? setTimeout(function () { controller.abort(); }, timeoutMs) : null;
149	    try {
150	      const headers = {'X-Latchkey-Share': shareId};
151	      if (body !== null && body !== undefined) { headers['Content-Type'] = 'application/json'; }
152	      const r = await fetch(path, {method: method, credentials: 'same-origin', cache: 'no-store',
153	                                   headers: headers, body: body === null ? undefined : body,
154	                                   signal: controller.signal});
155	      const text = await r.text();
156	      return {status: r.status, body: text, auth: r.headers.get('X-Auth-Required') !== null};
157	    } catch (e) {
158	      return {status: 0, body: '', auth: false};
159	    } finally {
160	      if (timer !== null) { clearTimeout(timer); }
161	    }
162	    """#
163	
164	    /// Stages one chunk of a shared document in the app's content world
165	    /// (F3 §4.6). `callAsyncJavaScript` passes strings, not bytes, so the
166	    /// file arrives as base64 of at most `ShareDelivery.chunkBytes` raw bytes
167	    /// per call. Arguments `id`, `index` and `chunk`. The parts live on the
168	    /// app world's `window`, which the page cannot see. Returns the number of
169	    /// parts staged; a chunk out of order clears the item and returns -1, so
170	    /// a retry can never append to a half-staged file.
171	    static let shareStageChunk = #"""
172	    const store = window.__latchkeyShare || (window.__latchkeyShare = {});
173	    if (index === 0) { store[id] = []; }
174	    const parts = store[id];
175	    if (!parts || parts.length !== index) { delete store[id]; return -1; }
176	    const bin = atob(chunk);
177	    const bytes = new Uint8Array(bin.length);
178	    for (let i = 0; i < bin.length; i++) { bytes[i] = bin.charCodeAt(i); }
179	    parts.push(new Blob([bytes]));
180	    return parts.length;
181	    """#
182	
183	    /// Uploads the staged parts as the page (F3 §4.6): one `file` part named
184	    /// `filename`, to `/api/upload/file`, the dashboard composer's route.
185	    /// Arguments `id`, `filename`, `parts` (the count the app staged) and
186	    /// `timeoutMs`. Returns what `shareFetch` returns; a staged count that is
187	    /// not `parts` is refused here, before anything is sent. The staged
188	    /// parts are dropped whatever happens.
189	    static let shareUpload = #"""
190	    const store = window.__latchkeyShare || {};
191	    const staged = store[id];
192	    const controller = new AbortController();
193	    const timer = timeoutMs > 0 ? setTimeout(function () { controller.abort(); }, timeoutMs) : null;
194	    try {
195	      if (!staged || staged.length !== parts) { return {status: -1, body: '', auth: false}; }
196	      const form = new FormData();
197	      form.append('file', new Blob(staged), filename);
198	      const r = await fetch('/api/upload/file', {method: 'POST', credentials: 'same-origin', body: form,
199	                                                 headers: {'X-Latchkey-Share': id}, signal: controller.signal});
200	      const text = await r.text();
201	      return {status: r.status, body: text, auth: r.headers.get('X-Auth-Required') !== null};
202	    } catch (e) {
203	      return {status: 0, body: '', auth: false};
204	    } finally {
205	      delete store[id];
206	      if (timer !== null) { clearTimeout(timer); }
207	    }
208	    """#
209	
210	    /// The name `blockedMarker` posts to, in the app's own content world.
211	    static let blockedMarkerHandler = "kiroBlocked"
212	    /// The id of the `<style>` element `blockedMarker` adds.
213	    static let blockedMarkerStyleID = "latchkey-blocked-marker"
214	    /// What VoiceOver reads for a blocked image, and what the L1 test finds.
215	    static let blockedMarkerLabel = "Image not loaded. Tap to open in Safari."
216	
217	    /// Marks images the content rule list blocked, and counts (F6 §4a).
218	    ///
219	    /// A rule list blocks silently: the page never learns why, and the app
220	    /// never sees the request. Injecting a marker element beside the image
221	    /// fights React, which reconciles it away on the next render, so this
222	    /// sets two attributes on the image React already owns: if React
223	    /// re-renders it, the load fails again and they are set again.
224	    ///
225	    ///  - A capture-phase `error` listener on `document` (`error` does not
226	    ///    bubble). An `img` whose http(s) source is off this document's
227	    ///    origin gets `data-latchkey-blocked="<absolute url>"` and an
228	    ///    `aria-label`. Off-origin `script`/`link` failures are counted as
229	    ///    blocked; same-origin `img`/`script`/`link` failures are counted as
230	    ///    the gateway's own — a wrong allow rule shows up as those, not as a
231	    ///    mystery blank page. Counts go to native 1 s after the last one, as
232	    ///    `{event: "counts", blocked, gatewayFailed}` increments: numbers,
233	    ///    never URLs.
234	    ///  - A `<style>` on `<html>` at document start (before `<head>` exists)
235	    ///    draws the marker: a 44 pt dashed box. `min-*` is what makes an
236	    ///    `alt=""` image visible at all; WebKit renders a failed one at 0×0.
237	    ///    No URL in it, so it depends on neither `img-src` nor the list.
238	    ///  - A capture-phase `click` listener. Trusted clicks only, so the
239	    ///    page's own `el.click()` cannot send anything out; a tap on a marked
240	    ///    image posts `{event: "open", url}` and does not reach the page's own
241	    ///    handler (a lightbox).
242	    ///  - After `load` and on a 2 s debounce after each new resource entry,
243	    ///    the origins of off-origin resources the page has loaded, as
244	    ///    increments `{event: "hosts", hosts: {origin: n}}`. A diagnostic of
245	    ///    which allowlisted CDNs were contacted (§4.1a), never evidence that a
246	    ///    block happened.
247	    ///
248	    /// Every frame (the one exception PageScripts' header asks to be
249	    /// justified): agent images render inside same-origin widget frames too.
250	    /// Runs in the app's own content world, so the page cannot post to it.
251	    /// If a future bundle swallows `error` events, the marker stops appearing
252	    /// and the blocking itself carries on.
253	    static let blockedMarker = #"""
254	    (function () {
255	      var handlers = window.webkit && window.webkit.messageHandlers;
256	      var handler = handlers && handlers.kiroBlocked;
257	      var ATTR = 'data-latchkey-blocked';
258	      var LABEL = 'Image not loaded. Tap to open in Safari.';
259	      function post(m) { try { if (handler) { handler.postMessage(m); } } catch (e) {} }
260	
261	      function absolute(u) {
262	        try {
263	          var x = new URL(u, document.baseURI);
264	          return (x.protocol === 'http:' || x.protocol === 'https:') ? x : null;
265	        } catch (e) { return null; }
266	      }
267	
268	      try {
269	        var style = document.createElement('style');
270	        style.id = 'latchkey-blocked-marker';
271	        style.textContent = 'img[' + ATTR + '] { display: inline-block; min-width: 44px; min-height: 44px; ' +
272	          'box-sizing: border-box; border: 1px dashed currentColor; border-radius: 6px; ' +
273	          'background-color: rgba(127,127,127,.15); cursor: pointer; }';
274	        document.documentElement.appendChild(style);
275	      } catch (e) {}
276	
277	      // Only images this script marked, with the URL it saw, count: a page
278	      // (or sanitized agent HTML, which keeps data-* attributes) can set
279	      // the attribute on anything, but cannot reach this world's map.
280	      var marked = new WeakMap();
281	      var blocked = 0, gatewayFailed = 0, countsTimer = null;
282	      function flushCounts() {
283	        countsTimer = null;
284	        if (!blocked && !gatewayFailed) { return; }
285	        post({event: 'counts', blocked: blocked, gatewayFailed: gatewayFailed});
286	        blocked = 0; gatewayFailed = 0;
287	      }
288	      function scheduleCounts() {
289	        if (countsTimer !== null) { clearTimeout(countsTimer); }
290	        countsTimer = setTimeout(flushCounts, 1000);
291	      }
292	
293	      document.addEventListener('error', function (e) {
294	        var el = e.target;
295	        if (!el || !el.tagName) { return; }
296	        var tag = String(el.tagName).toLowerCase(), raw = null;
297	        if (tag === 'img') { raw = el.currentSrc || el.src; }
298	        else if (tag === 'script') { raw = el.src; }
299	        else if (tag === 'link') { raw = el.href; }
300	        if (!raw) { return; }
301	        var url = absolute(raw);
302	        if (!url) { return; }
303	        if (url.origin === location.origin) { gatewayFailed += 1; scheduleCounts(); return; }
304	        blocked += 1;
305	        if (tag === 'img') {
306	          marked.set(el, url.href);
307	          el.setAttribute(ATTR, url.href);
308	          el.setAttribute('aria-label', LABEL);
309	        }
310	        scheduleCounts();
311	      }, true);
312	
313	      document.addEventListener('click', function (e) {
314	        if (!e.isTrusted) { return; }
315	        var t = e.target;
316	        var el = t && t.closest ? t.closest('img[' + ATTR + ']') : null;
317	        if (!el || !marked.has(el)) { return; }
318	        e.preventDefault();
319	        e.stopPropagation();
320	        post({event: 'open', url: marked.get(el)});
321	      }, true);
322	
323	      var hosts = {}, hostsTimer = null;
324	      function flushHosts() {
325	        hostsTimer = null;
326	        var any = false;
327	        for (var k in hosts) { if (Object.prototype.hasOwnProperty.call(hosts, k)) { any = true; break; } }
328	        if (!any) { return; }
329	        post({event: 'hosts', hosts: hosts});
330	        hosts = {};
331	      }
332	      function note(entries) {
333	        for (var i = 0; i < entries.length; i++) {
334	          var url = absolute(entries[i].name);
335	          if (!url || url.origin === location.origin) { continue; }
336	          hosts[url.origin] = (hosts[url.origin] || 0) + 1;
337	        }
338	        if (hostsTimer !== null) { clearTimeout(hostsTimer); }
339	        hostsTimer = setTimeout(flushHosts, 2000);
340	      }
341	      try {
342	        new PerformanceObserver(function (list) { note(list.getEntries()); })
343	          .observe({type: 'resource', buffered: true});
344	      } catch (e) {}
345	      window.addEventListener('load', function () {
346	        if (hostsTimer !== null) { clearTimeout(hostsTimer); flushHosts(); }
347	      });
348	    })();
349	    """#
350	
351	    /// The name `pageBackground` posts to. Registered in the app's own
352	    /// content world only, like the session bridge's.
353	    static let pageBackgroundHandler = "latchkeyPageBackground"
354	
355	    /// Reports the page's canvas colour (F9 §0.1 step 2): the strip above the
356	    /// web view is tinted with it, so page and strip read as one surface.
357	    ///
358	    /// Why not `WKWebView.themeColor`: KiroCrew 0.7.0 declares a fixed
359	    /// `theme-color` of `#0d0f12` and switches between twenty-odd dark AND
360	    /// light themes at runtime by `data-theme`, so the meta tag would paint a
361	    /// near-black bar above a light page. Why not `underPageBackgroundColor`:
362	    /// `RawWebView` overrides it to stop the pre-paint flash, and the getter
363	    /// then returns the override, not the page.
364	    ///
365	    /// The canvas takes `<html>`'s background, else `<body>`'s (CSS
366	    /// Backgrounds §2.11.2), which is what this reads. It posts the computed
367	    /// value — `rgb(…)`/`rgba(…)`, or `''` when the page paints nothing — on
368	    /// load, on attribute changes to `<html>`/`<body>` (a theme switch), on
369	    /// stylesheet insertion, on a colour-scheme change and after a background
370	    /// transition ends, coalesced to one read per frame and only on change.
371	    static let pageBackground = #"""
372	    (function () {
373	      var handlers = window.webkit && window.webkit.messageHandlers;
374	      var handler = handlers && handlers.latchkeyPageBackground;
375	      if (!handler) { return; }
376	      var last = null, pending = false;
377	      function clear(c) { return !c || c === 'transparent' || /^rgba\(.*,\s*0\)$/.test(c); }
378	      function read() {
379	        pending = false;
380	        var c = '';
381	        try {
382	          var d = document.documentElement, b = document.body;
383	          c = d ? getComputedStyle(d).backgroundColor : '';
384	          if (clear(c)) { c = b ? getComputedStyle(b).backgroundColor : ''; }
385	          if (clear(c)) { c = ''; }
386	        } catch (e) { c = ''; }
387	        if (c === last) { return; }
388	        last = c;
389	        try { handler.postMessage(c); } catch (e) {}
390	      }
391	      function schedule() {
392	        if (pending) { return; }
393	        pending = true;
394	        requestAnimationFrame(read);
395	      }
396	      var observer = new MutationObserver(function () {
397	        if (document.head) { observer.observe(document.head, {childList: true}); }
398	        if (document.body) { observer.observe(document.body, {attributes: true}); }
399	        schedule();
400	      });
401	      observer.observe(document.documentElement, {attributes: true, childList: true});
402	      document.addEventListener('DOMContentLoaded', schedule);
403	      window.addEventListener('load', schedule);
404	      document.addEventListener('transitionend', schedule, true);
405	      try { matchMedia('(prefers-color-scheme: dark)').addEventListener('change', schedule); } catch (e) {}
406	      schedule();
407	    })();
408	    """#
409	
410	    /// The name `activationReporter` posts to, in the app's own content world.
411	    static let activationHandler = "latchkeyActivation"
412	
413	    /// Tells the app the owner clicked (F17 §4.2): the one signal a page
414	    /// cannot forge. `isTrusted` is false for `el.click()` and
415	    /// `dispatchEvent`, and the handler exists only in the app's world, so
416	    /// neither can post to it. `click` alone: a tap, a keyboard activation
417	    /// and a form's implicit submit all produce one; scrolling and typing do
418	    /// not. On `window`, capturing, and installed at document start, so it
419	    /// runs before any listener the page adds and a page's
420	    /// `stopPropagation` cannot hide a click from it.
421	    static let activationReporter = #"""
422	    (function () {
423	      var h = window.webkit && window.webkit.messageHandlers
424	        && window.webkit.messageHandlers.latchkeyActivation;
425	      if (!h) { return; }
426	      window.addEventListener('click', function (e) {
427	        if (e.isTrusted) { try { h.postMessage(1); } catch (err) {} }
428	      }, true);
429	    })();
430	    """#
431	
432	    /// The name `appBarObserver` posts to, in the app's own content world.
433	    static let appBarHandler = "latchkeyAppBar"
434	
435	    /// Reports the finger's travel to the app bar (F15 §4a).
436	    ///
437	    /// Why a page script and not the web view's `UIScrollView`: KiroCrew
438	    /// 0.7.0's shell is `h-dvh` with `overflow-hidden` and inner scrollers,
439	    /// so the document never scrolls and the scroll view never moves. Only an
440	    /// element inside the page does, and WebKit reports that only to the page.
441	    ///
442	    /// It observes and never takes part. Every listener is `passive` (it
443	    /// cannot call `preventDefault`, so it cannot stop a scroll) and on
444	    /// `window` in the capture phase, which sees a scroll of ANY element
445	    /// without reading the page's markup (F15 §3). It lives in the app's
446	    /// content world, invisible to the page.
447	    ///
448	    /// Posts `{p: 's'|'m'|'e', dx, dy, r}`: a touch-down, a move coalesced to
449	    /// one per frame, a lift. dx/dy are screen points. `r` is the largest
450	    /// vertical scroll range of anything that scrolled during the touch — 0
451	    /// when nothing did, which is how a page too short to scroll is told
452	    /// apart from one that scrolls. A change of viewport size (the bar itself
453	    /// retracting) re-bases the finger instead of counting as travel.
454	    ///
455	    /// And `{p: 'x', r}`, the page's extent: the largest vertical scroll range
456	    /// of the document or of any element whose `overflow-y` lets it scroll
457	    /// (form controls aside), in screen points, touch or no touch. The bar is
458	    /// hidden by default, and a page with no range must keep it (F15 §4b), so
459	    /// the app has to know before the owner touches anything. Measured at most
460	    /// every 500 ms, after the document loads, resizes, mutates or scrolls, and
461	    /// posted when it changes and always at `load`. It reads layout, never
462	    /// the page's markup or text.
463	    static let appBarObserver = #"""
464	    (function () {
465	      var handlers = window.webkit && window.webkit.messageHandlers;
466	      var handler = handlers && handlers.latchkeyAppBar;
467	      if (!handler) { return; }
468	      var opts = {capture: true, passive: true};
469	      var active = false, pending = false, x = 0, y = 0, w = 0, h = 0, dx = 0, dy = 0, range = 0;
470	      var extent = -1, due = 0;
471	      function scale() { return window.visualViewport ? window.visualViewport.scale : 1; }
472	      function post(m) { try { handler.postMessage(m); } catch (e) {} }
